class BowlingGame:
    def __init__(self):
        self.rolls = []

    def roll(self, pins):
        # Validate pins basic range
        if not isinstance(pins, int):
            raise ValueError("Pins must have a value from 0 to 10")
        if pins < 0 or pins > 10:
            raise ValueError("Pins must have a value from 0 to 10")

        # If game already complete, cannot roll anymore
        if self._is_game_complete(self.rolls):
            raise IndexError("Cannot roll after game is over")

        # Validate by trying to build frames with the candidate roll appended
        candidate = self.rolls + [pins]
        try:
            frames, leftover = self._build_frames(candidate, allow_incomplete=True)
        except ValueError as e:
            # re-raise validation errors with their messages
            raise

        # If building frames produced more than 10 full frames and leftover rolls, it's invalid
        # (i.e., extra rolls beyond allowed fill balls)
        if len(frames) > 10:
            raise IndexError("Cannot roll after game is over")
        # If exactly 10 frames, ensure leftover is 0 (all accounted for in frames)
        # _build_frames will include tenth-frame fill balls in the tenth frame; leftover >0 indicates excess
        if len(frames) == 10 and leftover > 0:
            raise IndexError("Cannot roll after game is over")

        # If tenth frame is open (less than 10 pins total) and there are any bonus rolls attempted, disallow
        if len(frames) == 10:
            tenth = frames[9]
            # open tenth is two rolls summing to <10 OR single roll if incomplete
            if len(tenth) >= 2 and tenth[0] != 10 and (tenth[0] + tenth[1] < 10) and len(tenth) > 2:
                raise IndexError("cannot throw bonus with an open tenth frame")

        # If all validations pass, append the roll
        self.rolls.append(pins)

    def score(self):
        # Score only allowed at end of game
        if not self._is_game_complete(self.rolls):
            raise IndexError("Score cannot be taken until the end of the game")

        score = 0
        rolls = self.rolls
        i = 0
        for frame in range(1, 11):
            if rolls[i] == 10:
                # strike
                score += 10 + rolls[i + 1] + rolls[i + 2]
                i += 1
            else:
                frame_sum = rolls[i] + rolls[i + 1]
                if frame_sum == 10:
                    # spare
                    score += 10 + rolls[i + 2]
                else:
                    score += frame_sum
                i += 2
        return score

    # --------------------
    # Helper methods
    # --------------------
    def _is_game_complete(self, rolls):
        """
        Returns True if the provided rolls represent a complete game.
        """
        frames, leftover = self._build_frames(rolls, allow_incomplete=False)
        # Complete if we have exactly 10 frames and no leftover rolls
        return len(frames) == 10 and leftover == 0 and self._tenth_frame_complete(frames[9])

    def _tenth_frame_complete(self, tenth):
        """
        Returns True if the tenth frame (list of rolls) is complete.
        """
        if not tenth:
            return False
        first = tenth[0]
        if first == 10:
            # strike: need two bonus balls
            return len(tenth) == 3
        else:
            if len(tenth) < 2:
                return False
            if first + tenth[1] == 10:
                # spare: needs one bonus
                return len(tenth) == 3
            else:
                # open frame: exactly two rolls
                return len(tenth) == 2

    def _build_frames(self, rolls, allow_incomplete=True):
        """
        Build frames from rolls.

        Returns (frames, leftover) where frames is a list of frames (each a list of rolls),
        and leftover is number of rolls left unconsumed after up to 10 frames when allow_incomplete=True,
        or 0 if allow_incomplete=False and the rolls are fully valid for complete frames.

        Raises ValueError on invalid pin counts (e.g., frame sum > 10).
        Raises IndexError on impossible extra rolls when allow_incomplete=False.
        """
        frames = []
        i = 0
        n = len(rolls)
        for frame_no in range(1, 11):
            if i >= n:
                # no more rolls; if incomplete allowed, break and return
                if allow_incomplete:
                    return frames, 0 if i == n else n - i
                else:
                    return frames, n - i
            if frame_no < 10:
                first = rolls[i]
                if first == 10:
                    frames.append([10])
                    i += 1
                else:
                    # Need a second roll for this frame
                    if i + 1 >= n:
                        if allow_incomplete:
                            frames.append([first])
                            i += 1
                            return frames, 0
                        else:
                            raise IndexError("Incomplete frame")
                    second = rolls[i + 1]
                    if first + second > 10:
                        raise ValueError("Pin count exceeds pins on the lane")
                    frames.append([first, second])
                    i += 2
            else:
                # Tenth frame: can have 2 or 3 rolls depending
                remaining = n - i
                if remaining <= 0:
                    if allow_incomplete:
                        frames.append([])
                        return frames, 0
                    else:
                        raise IndexError("Incomplete tenth frame")
                first = rolls[i]
                if first == 10:
                    # strike: need two more rolls (may be less if incomplete allowed)
                    if remaining >= 3:
                        second = rolls[i + 1]
                        third = rolls[i + 2]
                        # If second is not a strike, second+third must not exceed 10
                        if second != 10 and second + third > 10:
                            raise ValueError("Pin count exceeds pins on the lane")
                        frames.append([first, second, third])
                        i += 3
                    else:
                        # incomplete tenth frame
                        if allow_incomplete:
                            frames.append(rolls[i:n])
                            return frames, 0
                        else:
                            raise IndexError("Incomplete tenth frame")
                else:
                    # first < 10
                    if remaining >= 2:
                        second = rolls[i + 1]
                        if first + second > 10:
                            raise ValueError("Pin count exceeds pins on the lane")
                        if first + second == 10:
                            # spare: may have one bonus ball
                            if remaining >= 3:
                                third = rolls[i + 2]
                                frames.append([first, second, third])
                                i += 3
                            else:
                                if allow_incomplete:
                                    frames.append([first, second] if remaining == 2 else rolls[i:n])
                                    return frames, 0
                                else:
                                    raise IndexError("Incomplete tenth frame")
                        else:
                            # open frame: exactly two rolls, no bonus allowed
                            frames.append([first, second])
                            i += 2
                    else:
                        # only one roll so far in tenth
                        if allow_incomplete:
                            frames.append([first])
                            return frames, 0
                        else:
                            raise IndexError("Incomplete tenth frame")
                break  # we've processed tenth frame; stop
        leftover = n - i
        return frames, leftover
